<?php
/** Proof — queues (spec "Proof", 2–3): a department's members "through IT", include_department off, a named member stays, the default assignee as an agent, the method without one → 422, archive the default → refused, archive another with open tickets → moved with ticket.assign rows. */
require __DIR__ . '/lib.php';
$owner = as_member(1); $marco = as_member(27); $lena = as_member(28);
$general = general_queue();

echo "1. A queue linked to a department\n";
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/queues/save.php', ['name' => 'SMOKE IT help', 'description' => 'SMOKE desk', 'department' => 5, 'include_department' => 'yes', 'assignment_method' => 'round_robin', 'sort_order' => 5]);
$qid = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $qid > 0 && ($b['location'] ?? '') === '/settings/queues/' . $qid . '?notice=saved', "queue_create: 200, record_id $qid, location the queue");
ok((string) one('SELECT key FROM queues WHERE id = :q', ['q' => $qid]) === 'smoke_it_help', 'the key was derived from the name (smoke_it_help)');
$log = activity('queue.create', $since);
ok(count($log) === 1 && (int) $log[0]['queue_id'] === $qid && str_contains((string) $log[0]['after'], '"department_id": 5'), 'queue.create is logged with queue_id and the fields');
[$c, $d] = screen($owner, '/settings/queues/' . $qid);
$through = array_values(array_filter($d['members'] ?? [], fn ($m) => $m['how'] === 'department'));
ok($c === 200 && count($through) >= 3 && in_array(27, array_column($through, 'member_id'), true) && in_array(40, array_column($through, 'member_id'), true), 'IT\'s members (Marco, Lena, the Frontline agent) appear "through IT" (' . count($through) . ')');
pdo()->exec("SELECT set_config('app.member_id', '27', false)");
ok(in_array($qid, array_map('intval', q('SELECT * FROM hd_held_queue_ids()') ? array_column(q('SELECT hd_held_queue_ids() AS id'), 'id') : []), true), 'hd_held_queue_ids() lists the queue for Marco');
$body = page($owner, '/settings/queues/' . $qid)['body'];
ok(str_contains($body, 'Through IT') && str_contains($body, 'Leave the department in the OS') && !str_contains($body, 'id="queue-member-27-remove-btn"'), 'the screen says "Through IT" and offers no Remove for them');
[$c, $b] = act($owner, '/settings/queues/member-remove.php', ['queue' => $qid, 'member' => 27]);
ok($c === 422 && str_contains(msg($b), 'Leave the department in the OS'), 'removing a department member here: 422 "Leave the department in the OS"');

echo "2. A named member stays when the department is unlinked\n";
[$c, $b] = act($owner, '/settings/queues/member.php', ['queue' => $qid, 'member' => 27, 'is_lead' => 'yes']);
ok($c === 200 && (bool) one('SELECT is_lead FROM queue_members WHERE queue_id = :q AND member_id = 27', ['q' => $qid]), 'Marco named as lead: 200, is_lead');
ok(count(activity('queue.member_add', $since)) === 1 && str_contains((string) activity('queue.member_add', $since)[0]['after'], '"is_lead": true'), 'queue.member_add logged with is_lead');
$since2 = last_activity_id();
[$c, $b] = act($owner, '/settings/queues/save.php', ['queue' => $qid, 'include_department' => 'no']);
ok($c === 200 && (string) one('SELECT name FROM queues WHERE id = :q', ['q' => $qid]) === 'SMOKE IT help' && !(bool) one('SELECT include_department FROM queues WHERE id = :q', ['q' => $qid]), 'queue_update with one field: the rest stays (name kept, include_department off)');
$log = activity('queue.update', $since2);
ok(count($log) === 1 && json_decode((string) $log[0]['after'], true) === ['include_department' => false] && json_decode((string) $log[0]['before'], true) === ['include_department' => true], 'queue.update logs only the changed field, before and after');
[$c, $d] = screen($owner, '/settings/queues/' . $qid);
ok(count($d['members']) === 1 && $d['members'][0]['member_id'] === 27 && $d['members'][0]['is_lead'] && $d['members'][0]['how'] === 'named', 'now only Marco, named, lead');
pdo()->exec("SELECT set_config('app.member_id', '28', false)");
ok(array_column(q('SELECT hd_held_queue_ids() AS id'), 'id') === [] || !in_array($qid, array_map('intval', array_column(q('SELECT hd_held_queue_ids() AS id'), 'id')), true), 'Lena no longer holds it');
[$c, $b] = act($marco, '/settings/queues/member.php', ['queue' => $qid, 'member' => 28]);
ok($c === 200 && one('SELECT 1 FROM queue_members WHERE queue_id = :q AND member_id = 28', ['q' => $qid]) !== false, 'the queue\'s lead (Marco, no queues.members right) may add a member (hd_is_queue_lead)');
[$c, $b] = act($marco, '/settings/queues/member-remove.php', ['queue' => $qid, 'member' => 28]);
ok($c === 200 && one('SELECT 1 FROM queue_members WHERE queue_id = :q AND member_id = 28', ['q' => $qid]) === false && count(activity('queue.member_remove', $since2)) === 1, 'and remove one; queue.member_remove logged');
[$c, $b] = act($owner, '/settings/queues/member.php', ['queue' => $qid, 'member' => 4242]);
ok($c === 422 && msg($b) === 'That member is not active here.', 'an unknown member: 422');

echo "3. Validation and the default assignee\n";
[$c, $b] = act($owner, '/settings/queues/save.php', ['name' => 'SMOKE Needs one', 'assignment_method' => 'default_assignee']);
ok($c === 422 && isset(fields($b)['default_assignee']) && str_contains(msg($b), 'Name a default assignee'), 'method Default assignee without one: 422 with the field error');
[$c, $b] = act($owner, '/settings/queues/save.php', ['name' => 'SMOKE Agent desk', 'assignment_method' => 'default_assignee', 'default_assignee' => 40]);
$aq = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $aq > 0, 'with the Frontline agent (40) as default assignee: saved');
[$c, $d] = screen($owner, '/settings/queues/' . $aq);
ok($d['queue']['default_assignee']['kind'] === 'agent' && $d['queue']['assignment'] === 'Goes to SMOKE Frontline', 'the queue says "Goes to SMOKE Frontline" and the assignee\'s kind is agent');
$body = page($owner, '/settings/queues/' . $aq)['body'];
ok(str_contains($body, 'Goes to SMOKE Frontline') && preg_match('/id="queue-view-assignment">.*?badge[^>]*>Agent</s', $body) === 1, 'the screen shows it with the Agent chip');
[$c, $b] = act($owner, '/settings/queues/save.php', ['name' => 'SMOKE IT help']);
ok($c === 422 && str_contains(msg($b), 'already exists'), 'a second queue with the same name: 422');
[$c, $b] = act($owner, '/settings/queues/save.php', ['name' => 'SMOKE Keyed', 'key' => 'smoke_it_help']);
ok($c === 422 && str_contains(msg($b), 'already in use'), 'a key in use: 422');
[$c, $b] = act($owner, '/settings/queues/save.php', ['name' => 'SMOKE Dept gone', 'department' => 999]);
ok($c === 422 && isset(fields($b)['department']), 'a department the mirror does not know: 422 (field department)');
[$c, $b] = act($owner, '/settings/queues/save.php', ['queue' => $qid, 'key' => 'other_key']);
ok($c === 200 && (string) one('SELECT key FROM queues WHERE id = :q', ['q' => $qid]) === 'smoke_it_help', 'the key is immutable after create (a sent key is ignored)');
[$c, $b] = act($owner, '/settings/queues/save.php', ['name' => 'SMOKE Bad mail', 'email_address' => 'not-an-address']);
ok($c === 422 && isset(fields($b)['email_address']), 'a bad email address: 422');
ok(page($lena, '/settings/queues/')['code'] === 200 && str_contains(page($lena, '/settings/queues/')['body'], 'id="queue-card-' . $qid . '"') && !str_contains(page($lena, '/settings/queues/')['body'], 'id="queues-list-add-btn"'), 'a lead sees the cards without the Add button');
$body = page($owner, '/settings/queues/')['body'];
ok(str_contains($body, 'id="queue-card-' . $general . '-default"') && str_contains($body, 'id="queue-card-' . $qid . '"') && str_contains($body, 'IT · members join') === false, 'the list: General wears the Default badge; the unlinked queue has no department chip');

echo "4. Archive\n";
[$c, $b] = act($owner, '/settings/queues/archive.php', ['queue' => $general]);
ok($c === 422 && msg($b) === 'Choose another default queue first.', 'archiving the default queue: 422 "Choose another default queue first."');
$req = requester_of_member(26);
$t1 = mkticket($req, $qid, 'SMOKE open one'); $t2 = mkticket($req, $qid, 'SMOKE open two', 'open'); $t3 = mkticket($req, $qid, 'SMOKE solved', 'solved');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/queues/archive.php', ['queue' => $qid]);
ok($c === 200 && ($b['moved_tickets'] ?? []) == [$t1, $t2], 'archiving a queue with two open tickets (and a solved one): 200, the two moved');
ok((int) one('SELECT queue_id FROM tickets WHERE id = :t', ['t' => $t1]) === $general && (int) one('SELECT queue_id FROM tickets WHERE id = :t', ['t' => $t2]) === $general && (int) one('SELECT queue_id FROM tickets WHERE id = :t', ['t' => $t3]) === $qid, 'both are in General; the solved one stayed');
$moves = activity('ticket.assign', $since);
ok(count($moves) === 2 && (int) $moves[0]['ticket_id'] === $t1 && (int) $moves[0]['queue_id'] === $general && str_contains((string) $moves[0]['after'], 'queue_archive'), 'two ticket.assign rows (ticket_id, queue_id, via queue_archive)');
ok(count(activity('queue.archive', $since)) === 1 && str_contains((string) activity('queue.archive', $since)[0]['after'], '"moved_tickets": 2'), 'queue.archive logged with moved_tickets');
ok(page($owner, '/settings/queues/' . $qid)['code'] === 404 && !str_contains(page($owner, '/settings/queues/')['body'], 'id="queue-card-' . $qid . '"'), 'the archived queue is gone from the list and its page');
[$c, $b] = act($owner, '/settings/queues/archive.php', ['queue' => $qid]);
ok($c === 422, 'archiving it again: 422');
finish();
